-- ---------------------------------------------------------------- fields: quoted
-- einleitungsart (M760-01, M760-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Regelfall der Einleitung von fetthaltigem Abwasser ist die Indirekteinleitung in ein öffentliches Kanalnetz (siehe Bild 1). In seltenen Fällen kann aber auch eine Direkteinleitung in ein Gewässer in Betracht kommen (siehe Bild 2). | Einleitung von (ggf. vorbehandeltem) Abwasser in eine öffentliche Kläranlage und somit indirekt über diese Kläranlage in ein Gewässer | Einleitung von behandeltem Abwasser direkt in ein Gewässer und nicht in ein öffentliches Kanalnetz — printed p.22 (§4.1; Definitionen §3.1, p.18)', verification_note='md-verified 2026-09-05 (§4.1 + §3.1, printed p.22/18) [VC]', verified_at=now() where id in ('79ff9c64-fbde-4ab6-89a8-0f2dd896a47d','4fec98c5-2304-4137-90d8-cae2a3cf98f4') and verification_status not in ('verified_against_standard','corrected');
-- branchentyp (M760-01, M760-08)
update public.fields set verification_status='verified_against_standard', verification_quote='Das vorliegende Merkblatt gilt für den Anfall von und den Umgang mit fetthaltigem Abwasser sowohl aus privaten als auch aus unterschiedlichen gewerblichen Quellen. So werden Menge und Beschaf- fenheit von Abwasser in Küchenbetrieben ebenso beschrieben wie Abwasser aus Kindertagesstätten, Bäckereien, Fleischereien oder Supermärkten bis hin zur Beschreibung von Spezialbetrieben mit fetthaltigem Abwasser. — printed p.14', verification_note='md-verified 2026-09-05 (§1, printed p.14) [VC]', verified_at=now() where id in ('a46b0fad-4dba-467b-bddf-5e366ddbf6f3','11081f79-358a-4011-94ac-b917219875a7') and verification_status not in ('verified_against_standard','corrected');
-- rueckstauebene (M760-01)
update public.fields set verification_status='verified_against_standard', verification_quote='Ein möglicher Aufstau im Abscheider aufgrund von Rückstau aus dem Kanal birgt die Gefahr des Austritts von fetthaltigem Abwasser aus der Anlage und behindert die Durchlüftung (Bild 39). Daher ist in den geltenden Normen (z. B. DIN EN 1825-2) eine Sicherung gegen Rückstau vorgeschrieben. Jeder Fettabscheider, bei dem die Sohle des Auslaufs unter der Rückstauebene liegt, muss gegen Rückstau geschützt werden. Dies vermeidet neben einem Aufstau auch eine Aufkonzentration der Faulgase und damit — printed p.92', verification_note='md-verified 2026-09-05 (§10.1.10, printed p.92) [VC]', verified_at=now() where id in ('7145e189-02b7-42c1-a9d0-ac124e75762b') and verification_status not in ('verified_against_standard','corrected');
-- keller_vorhanden (M760-01)
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Fall, dass kein Kellerraum zur Verfügung steht, gibt es unter bestimmten Voraussetzungen die Möglichkeit, den Fettabscheider außerhalb des Gebäudes in einem beheizten Container oder einfachen Anbau unterzubringen (siehe Bild 36 und Bild 37). Beim Bau dieser Aufstellungsform ist zu beachten, dass die erforderliche Zulaufhöhe aus dem Gebäude in der Regel bei ca. 400 mm über GOK liegt. Damit ist es konstruktiv notwendig, den Fettabscheider leicht vertieft einzubauen (siehe Bild 37). — printed p.89', verification_note='md-verified 2026-09-05 (§10.1.3, printed p.89 — clause_reference says §4.1; retag proposed in the STAGED file) [VC]', verified_at=now() where id in ('6d212bec-400f-4dcf-8502-75bef451cfb5') and verification_status not in ('verified_against_standard','corrected');
