-- c_lipophil_haus (M760-07, M760-09)
update public.fields set verification_status='verified_against_standard', verification_quote='Pro Einwohner und Tag wird nach vorliegenden Erhebungen insgesamt eine Menge von ca. 2 g bis 6 g Fett ins Abwasser eingetragen, was einer Konzentration an lipophilen Stoffen von $18 \mathrm{mg} / \mathrm{l}$ bis $55 \mathrm{mg} / \mathrm{l}$ entspricht (Koppe \& Stozek 1998, SEDD 2020). | Nach aktuellen Untersuchungen in zwei Großstädten werden in den von häuslichem Abwasser geprägten Kläranlageneinzugsgebieten ohne Industrieeinfluss Mittelwerte zwischen $38 \mathrm{mg} / \mathrm{l}$ und $86 \mathrm{mg} / \mathrm{l}$ lipophile Stoffe gemessen (Tabelle 7). — printed p.33', verification_note='md-verified 2026-09-05 (§7.1, printed p.33) [VC]', verified_at=now() where id in ('278136c8-ad3f-45f5-90ef-72c12592c097','df63805e-8d74-44f5-9ae6-5363e6adae5b') and verification_status not in ('verified_against_standard','corrected');
