-- kuechentyp (M760-07, M760-08)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Abwasseranfall und die enthaltenen Feststoff- und Fettanteile sind abhängig von: | I Betriebstyp der Küche: | Küchentyp, in dem verzehrfertige Speisen vollständig aus Rohprodukten zubereitet werden. In dieser Küche werden umfangreiche Arbeitsprozesse in mehreren, aufeinander folgenden Verarbeitungsstufen in Eigenleistung ausgeführt. | Küchentyp ohne Zubereitungsprozesse. Fertige, warme und kalte Speisen werden täglich unmittelbar kurz vor der Speisenausgabe aus externen Betriebstätten in temperierten Transportbehältnissen angeliefert. — printed p.35 (§7.2.3.1) und p.16-19 (§3.1)', verification_note='md-verified 2026-09-05 (§7.2.3.1 + §3.1, printed p.35/16-19) [VC]', verified_at=now() where id in ('528424ab-9053-4e78-bbc0-2fca4faee30f','c71df094-f275-4f07-a15b-29cc5b54fb22') and verification_status not in ('verified_against_standard','corrected');
-- verpflegungssystem (M760-07, M760-08)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Abwasseranfall und die enthaltenen Feststoff- und Fettanteile sind abhängig von: | I Verpflegungssystem: | Die im „Cook \& Chill"-Verfahren produzierten und gekühlten Speisen können bei ununterbrochener Kühlkette bis zu vier Tagen ohne Qualitätsverlust gelagert werden. | Speisen und/oder Speisenkomponenten, die im „Cook \& Freeze"-Verfahren produziert wurden, sind bei ununterbrochener Kühlkette im Tiefkühlraum produktabhängig bis zu zwölf Monate lagerungsfähig. — printed p.35 (§7.2.3.1) und p.18 (§3.1)', verification_note='md-verified 2026-09-05 (§7.2.3.1 + §3.1, printed p.35/18) [VC]', verified_at=now() where id in ('8d140de9-c67e-4b11-81c3-18fd0027937a','e5a44f7c-e476-4f99-8810-b5b5a8a4539d') and verification_status not in ('verified_against_standard','corrected');
-- convenience_grad (M760-07, M760-08)
update public.fields set verification_status='verified_against_standard', verification_quote='\caption{Tabelle 1: Beispiele zur Einteilungsstruktur in Convenience-Grade} | \hline Grad & Lebensmitteltyp & Beispiele \\ | \hline 0 & Frische Lebensmittel & Nicht zerlegtes Fleisch, ungewaschenes, ungeschältes Gemüse, Reis, Mehl \\ | \hline 5 & Verzehr-/tischfertige Lebensmittel & Kalte Soßen, fertige Salate, Obstkonserven, Desserts \\ | I Convenience-Grad der in der Küche verarbeiteten Produkte; — printed p.17', verification_note='md-verified 2026-09-05 (§3.1 Tabelle 1, printed p.17) [VC]', verified_at=now() where id in ('36fe9c8a-e902-4483-b5ca-3ffe4468017e','42213096-17d2-4067-b626-0961dabbe93b') and verification_status not in ('verified_against_standard','corrected');
-- anteil_abscheidbar_pct (M760-07, M760-09)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Anteil an nicht abscheidbaren Fetten im Küchenabwasser kann sehr unterschiedlich sein. In drei untersuchten Küchenbetrieben lag er bei $7,7 \%, 13,7 \%$ und $63 \%$ (Belouschek et al. 1994). Die Ergebnisse einer Studie der Deutschen Bundesstiftung Umwelt bestätigen tendenziell die überwiegende Abscheidbarkeit der Fette mit einem Anteil von etwa $60 \%$ bis $80 \%$ (SbieschNI 2004). — printed p.38', verification_note='md-verified 2026-09-05 (§7.2.4.2, printed p.38 — ACHTUNG: 7,7/13,7/63 % sind laut Quelle NICHT abscheidbare Anteile; die encodete description dreht das um (STAGED)) [VC]', verified_at=now() where id in ('1f84bf37-3e2a-4518-9aaa-cf2d689a1dfb','a3218a76-7624-4238-8b77-11e7c934abac') and verification_status not in ('verified_against_standard','corrected');
-- c_h2s_ppm (M760-08, M760-11)
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund der gesundheitlichen Gefahren, die von Schwefelwasserstoff ausgehen, ist der Arbeitgeber nach europäischem und deutschem Recht verpflichtet, das bindende Schutzziel für Beschäftigte in Form des Arbeitsplatzgrenzwerts (AGW) mit einer Begrenzung der $\mathrm{H}_{2} \mathrm{~S}$-Belastung auf 5 ppm (über 8 h ) bzw. 10 ppm (nicht mehr als 15 min ) zu gewährleisten (ElgETI et al. 2015). | Die Dosierung von Nitratlösung in den Fettabscheider führt dagegen zu deutlicher Verringerung der $\mathrm{H}_{2} \mathrm{~S}$-Belastung mit maximal 5 ppm . — printed p.56 (§8.2.8) und p.105 (§10.3.2)', verification_note='md-verified 2026-09-05 (§8.2.8 + §10.3.2, printed p.56/105) [VC]', verified_at=now() where id in ('cb89d6d3-24cc-4dff-9673-86f844510cd9','fa318f3e-1d03-4d4b-9815-0384b53c96bc') and verification_status not in ('verified_against_standard','corrected');
-- bauform_fa (M760-09, M760-13)
update public.fields set verification_status='verified_against_standard', verification_quote='I Fettabscheider mit integriertem Schlammfang in einem Behälter (siehe Bauform 1), | I Fettabscheider mit räumlich getrenntem Schlammfang in einem Behälter (siehe Bauform 2), | I Fettabscheider und Schlammfang in zwei getrennten Behältern (siehe Bauform 3). | \caption{Tabelle 29: Übersicht über die verschiedenen Bauformen einer Fettabscheideranlage (Bezeichnung der verschiedenen Bauteile gemäß Bild 21)} | hline Bauform 1 & Schlammfang mit integriertem Fettabscheider in einem Behälter | hline Bauform 2 & Schlammfang mit räumlich getrenntem Fettabscheider in einem Behälter | hline Bauform 3 & Schlammfang und Fettabscheider in zwei getrennten Behältern — printed p.65-66', verification_note='md-verified 2026-09-05 (§9.1.2 Tabelle 29, printed p.65-66) [VC]', verified_at=now() where id in ('1453384a-d299-4d3d-8864-bba2607705a5','7e565983-f6f6-4e75-8673-f06cfcd01071') and verification_status not in ('verified_against_standard','corrected');
-- entleerintervall_d (M760-10, M760-23)
update public.fields set verification_status='verified_against_standard', verification_quote='Fettabscheideranlagen werden gemäß DIN EN 1825-1 in der Regel so konzipiert, dass eine regelmäßige Entleerung des Gesamtinhalts gemäß den Vorgaben nach DIN EN 1825-2 erfolgt. Dabei wird der Fett- und Schlammsammelraum so bemessen, dass die Entleerung in der Regel monatlich durchgeführt wird. | Nach den geltenden Normen (DIN EN 1825-2, DIN 4040-100) ist der Abscheider nach der monatlichen Entleerung zu reinigen. — printed p.66 (§9.1.2) und p.99 (§10.2.4)', verification_note='md-verified 2026-09-05 (§9.1.2 + §10.2.4, printed p.66/99) [VC]', verified_at=now() where id in ('ba973600-80d7-42e6-a391-d2639b15c248','881373cd-9c4a-407f-bdce-f2e7664e8b9e') and verification_status not in ('verified_against_standard','corrected');
-- entleerintervall_teil_d (M760-09, M760-16)
update public.fields set verification_status='verified_against_standard', verification_quote='I Entnahme der leichten und gegebenenfalls schweren Phase in kurzen Zeitabständen (abhängig von Anfall und Speichervolumen meist täglich); | \hline Entleerung & Fettentnahme täglich Komplettentleerung mindestens wöchentlich & Monatlich oder bei maximal zulässiger Menge Fett- oder Schlammspeicher \\ — printed p.67 (§9.1.3) und p.70 (Tabelle 31)', verification_note='md-verified 2026-09-05 (§9.1.3 + Tabelle 31, printed p.67/70) [VC]', verified_at=now() where id in ('92189b6d-bc96-40b9-9d29-a653b532a086','6c28ea32-7783-459f-b09f-e09be84dc8ec') and verification_status not in ('verified_against_standard','corrected');
