update public.fields set verification_status='verified_against_standard', verification_quote='I Komplettentleerung nur bei einer Wartung spätestens jährlich bzw. bei einer Generalinspektion alle fünf Jahre; | Gemäß DIN 4040-100 ist eine monatliche Eigenkontrolle und eine jährliche Wartung durch einen Sachkundigen ${ }^{71}$ vorgeschrieben und mit konkreten Aufgaben belegt. — printed p.67 (§9.1.3) und p.98 (§10.2.3)', verification_note='md-verified 2026-09-05 (§9.1.3 + §10.2.3, printed p.67/98) [VC]', verified_at=now() where id in ('2b415255-5332-468f-9e28-3eacd94f905d','410d8ca8-258b-4b4b-9c4d-a83da3f5f8dc') and verification_status not in ('verified_against_standard','corrected');
