update public.fields set verification_status='verified_against_standard', verification_quote='I Komplettentleerung nur bei einer Wartung spätestens jährlich bzw. bei einer Generalinspektion alle fünf Jahre; | Der Betreiber einer Fettabscheideranlage ist verpflichtet, gemäß DIN EN 1825/DIN 4040-100 vor Inbetriebnahme und danach in regelmäßigen Abständen von maximal 5 Jahren den Abscheider durch eine fachkundige Person einer Generalinspektion mit Dichtheitsprüfung unterziehen zu lassen (siehe 10.2.5). | Der genaue Umfang einer alle fünf Jahre wiederkehrenden Generalinspektion ist in DIN 4040-100: 2016 in 10.7.2 ausführlich beschrieben. — printed p.67, 98 und 101', verification_note='md-verified 2026-09-05 (§9.1.3/§10.2.2/§10.2.5, printed p.67/98/101) [VC]', verified_at=now() where id in ('e5630104-e541-43fd-b06f-38b06e825c8e','45322806-63eb-4e0a-935c-a9b67d1dfb89') and verification_status not in ('verified_against_standard','corrected');
