-- abwassermenge_jahr (M760-09)
update public.fields set verification_status='verified_against_standard', verification_quote='Eine andere Variante wird im Mitteilungsblatt des Hessischen Städte- und Gemeindebundes vorgeschlagen, indem hinsichtlich des Abwasseranfalls eine Bagatellgrenze von $1 \mathrm{~m}^{3} / \mathrm{d}$ laufgerundet $500 \mathrm{~m}^{3} / \mathrm{a}$ ) eingeführt wird (Schöcke \& Fabry 2011). — printed p.124', verification_note='md-verified 2026-09-05 (Anhang A.4, printed p.124 — Bagatellgrenze für den Verzicht auf einen Fettabscheider) [VC]', verified_at=now() where id in ('543f6b56-8bd7-48c7-828e-e85c4a03248b') and verification_status not in ('verified_against_standard','corrected');
-- frischwassermenge_jahr (M760-09)
update public.fields set verification_status='verified_against_standard', verification_quote='Da die Abwassermenge in den seltensten Fällen gemessen wird, sollte dem Vorschlag gemäß hilfsweise die Frischwassermenge abzüglich einer Menge von $50 \mathrm{~m}^{3} /$ a pro angeschlossenen Einwohner herangezogen werden. Die Frischwassermenge ist leicht feststellbar und ein solcher Schwellenwert daher einfach umsetzbar. — printed p.124', verification_note='md-verified 2026-09-05 (Anhang A.4, printed p.124) [VC]', verified_at=now() where id in ('389210a1-519c-4c88-b23f-bb3a4e4aa988') and verification_status not in ('verified_against_standard','corrected');
-- kuehlwasser_absalzung (M760-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Dabei muss zur Vermeidung von Aufsalzung aus dem Kühlkreislauf (quasi-)kontinuierlich Wasser abgesalzt werden, das als Abwasser anfällt. Dieses Absalzungswasser enthält gegebenenfalls nicht abreagierte Reste des Biozids und bedarf bei Überschreitung einer Schwellenmenge von $10 \mathrm{~m}^{3} /$ Woche einer wasserrechtlichen Einleitungsgenehmigung nach § 58 WHG. — printed p.131', verification_note='md-verified 2026-09-05 (Anhang B.3, printed p.131) [VC]', verified_at=now() where id in ('4e57bc69-1241-4c95-9ec6-f8fbb647175f') and verification_status not in ('verified_against_standard','corrected');

