-- ---------------------------------------------------------------- equations: quoted
-- EQ-M760-02 (M760-09, M760-15)
update public.equations set verification_status='verified_against_standard', verification_quote='Gemäß DIN EN 1825-2:2002 Unterabschnitt 6.1, kann einem erhöhten Fettanfall im Abwasser durch die Wahl einer höheren Abscheidernenngröße oder eine häufigere Entleerung als ansonsten üblich Rechnung getragen werden. Die minimale Nenngröße richtet sich dabei nach dem maximal zu erwartenden Abwasservolumenstrom. — printed p.42', verification_note='md-verified 2026-09-05 (§7.2.6.3, printed p.42) [VC]', verified_at=now() where id in ('2ffe9ec8-e7d8-41bc-8546-6349881acb06','12244089-c454-4436-a855-6fba6946ea86') and verification_status <> 'verified_against_standard';
-- EQ-M760-03 (M760-07, M760-09)
update public.equations set verification_status='verified_against_standard', verification_quote='Pro Einwohner und Tag wird nach vorliegenden Erhebungen insgesamt eine Menge von ca. 2 g bis 6 g Fett ins Abwasser eingetragen, was einer Konzentration an lipophilen Stoffen von $18 \mathrm{mg} / \mathrm{l}$ bis $55 \mathrm{mg} / \mathrm{l}$ entspricht (Koppe \& Stozek 1998, SEDD 2020). | So wurden die Bilanzierungen in älteren Publikationen mit einem Wasserverbrauch von 200 L pro Person und Tag vorgenommen, wogegen nach Angaben des Umweltbundesamts im Jahre 2023 im Mittel 123 I Trinkwasser pro Person und Tag verbraucht wurden; allerdings kann der durchschnittliche Verbrauch je nach Bundesland stark schwanken (Hamburg: 140 l, Sachsen: 90 l). | Die tägliche Fettfracht pro Person liegt dabei rechnerisch bei ca. 6 g Fett. — printed p.33', verification_note='md-verified 2026-09-05 (§7.1, printed p.33 — CAVEAT: die Richtlinie druckt die Fracht direkt, nicht als Produkt; c_lipophil_haus [mg/l] x wasserverbrauch_pe_d [l/(P·d)] ergibt mg/(P·d), das Ausgabefeld führt g/(P·d) (STAGED)) [VC]', verified_at=now() where id in ('ff782b49-a7f0-4fd7-a4cd-754009d053c9','17bf4db7-5a0a-4fca-bc61-94e7e1ebbd64') and verification_status <> 'verified_against_standard';
